	private static List<String> drain(SlotPlan plan, Fixture fixture) throws IOException {
		return drain(plan.open(fixture.row), fixture);
	}

	private static List<String> drain(RowCursor cursor, Fixture fixture) throws IOException {
		List<String> rows = new ArrayList<>();
		try (cursor) {
			while (cursor.next()) {
				rows.add(value(fixture, "seed") + "|" + value(fixture, "candidate"));
			}
		}
		rows.sort(String::compareTo);
		assertFalse(fixture.row.view.hasBinding("candidate"), "a rejected or released pair leaves no RHS binding");
		return rows;
	}

	private static String value(Fixture fixture, String name) {
		return fixture.row.view.hasBinding(name)
				? fixture.row.view.getValue(name).stringValue().substring(Fixture.NS.length())
				: "UNBOUND";
	}

	private static SlotPlan tracked(SlotPlan delegate, AtomicInteger opens, AtomicInteger closes,
			RuntimeException cleanupFailure) {
		return new SlotPlan() {
			@Override
			public RowCursor open(RowState row) throws IOException {
				opens.incrementAndGet();
				RowCursor input = delegate.open(row);
				return new RowCursor() {
					boolean closed;

					@Override
					public boolean next() throws IOException {
						return input.next();
					}

					@Override
					public void close() {
						if (closed)
							return;
						closed = true;
						closes.incrementAndGet();
						input.close();
						if (cleanupFailure != null)
							throw cleanupFailure;
					}
				};
			}

			@Override
			public long producedMask() {
				return delegate.producedMask();
			}
		};
	}

	private static final class CountingCondition implements NativeBooleanFilter {
		final NativeLmdbQuerySource expectedSource;
		final AtomicInteger calls = new AtomicInteger(), closes = new AtomicInteger(), forks = new AtomicInteger();
		CountingCondition worker;
		Error cleanupFailure;
		boolean exhausted, incomplete;

		CountingCondition(NativeLmdbQuerySource source) {
			expectedSource = source;
		}

		@Override
		public boolean accept(RowState row) {
			assertSame(expectedSource, row.source);
			assertTrue(row.view.hasBinding("seed"));
			assertTrue(row.view.hasBinding("candidate"));
			calls.incrementAndGet();
			return row.view.getValue("seed").equals(row.view.getValue("candidate"));
		}

		@Override
		public boolean parallelWorkerForkable() {
			return true;
		}

		@Override
		public NativePredicateCapabilities capabilities() {
			return NativePredicateCapabilities.snapshot(3L, true, true);
		}

		@Override
		public NativeBooleanFilter forkForParallelWorker(NativeScalarPlan.WorkerContext context) {
			forks.incrementAndGet();
			return worker = new CountingCondition(context.source());
		}

		@Override
		public void inputExhausted() {
			exhausted = true;
		}

		@Override
		public void incompleteInput() {
			incomplete = true;
		}

		@Override
		public void close() {
			closes.incrementAndGet();
			if (cleanupFailure != null)
				throw cleanupFailure;
		}
	}

